contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "N >= 1 and M >= 1 and Q >= 1",
      "description": "The number of factories N, businessmen M, and years Q are all at least 1."
    },
    {
      "id": "P2",
      "expression": "len(parents) == N - 1",
      "description": "The parents list contains exactly N-1 integers representing the parent of nodes 2 to N."
    },
    {
      "id": "P3",
      "expression": "all(1 <= p <= i for i, p in enumerate(parents, start=2))",
      "description": "For each factory i from 2 to N, its parent p satisfies 1 <= p < i, ensuring a valid tree structure rooted at 1."
    },
    {
      "id": "P4",
      "expression": "len(B) == N and all(1 <= b <= M for b in B)",
      "description": "The ownership list B has N integers, each representing a valid businessman index between 1 and M."
    },
    {
      "id": "P5",
      "expression": "len(thresholds) == M and all(1 <= t <= 10**18 for t in thresholds)",
      "description": "The thresholds list has M integers, each representing a valid threshold amount."
    },
    {
      "id": "P6",
      "expression": "all(1 <= F <= N and 1 <= X <= 10**6 and 0 <= D <= 10**6 for F, X, D in queries)",
      "description": "Each query (F, X, D) satisfies the constraints: F is a valid factory, X is positive, and D is non-negative."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output_lines) == M",
      "description": "The output consists of exactly M lines, one for each businessman."
    },
    {
      "id": "Q2",
      "expression": "all((output_lines[i] == 'rekt') or (output_lines[i].isdigit() and 1 <= int(output_lines[i]) <= Q) for i in range(M))",
      "description": "Each output line is either the string 'rekt' or a valid year number between 1 and Q."
    },
    {
      "id": "Q3",
      "expression": "all((output_lines[i] == 'rekt') == (total_earnings[i] < thresholds[i]) for i in range(M))",
      "description": "For each businessman i, the output is 'rekt' if and only if their total earnings after Q years are strictly less than their threshold."
    },
    {
      "id": "Q4",
      "expression": "all((output_lines[i] != 'rekt') == (total_earnings[i] >= thresholds[i]) and (output_lines[i] != 'rekt' implies int(output_lines[i]) is the smallest year y such that cumulative_earnings[i] at year y >= thresholds[i]) for i in range(M))",
      "description": "For each businessman i, if they reach their threshold, the output is the smallest year index y (1-based) such that the cumulative earnings of all factories owned by businessman i up to year y is at least thresholds[i]."
    },
    {
      "id": "Q5",
      "expression": "all(cumulative_earnings[i] at year y == sum of (X + D * dist(F, G)) for all queries (F, X, D) in years 1..y and all factories G owned by businessman i where dist(F, G) is the number of edges on the path from F to G) for i in range(M)",
      "description": "The cumulative earnings for businessman i at any year y is the sum of donations received by all factories owned by i, where a donation from factory F with parameters (X, D) contributes X + D * dist(F, G) to factory G if G is in
